function resolveBricks(state, prevX, prevY) {
  const { ball, bricks } = state;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;
  const r = ball.r;

  let firstT = Infinity;      // earliest time of impact among live bricks
  let firstFace = null;       // resolution face for the earliest hit
  let firstBrick = null;
  const sameT = [];           // bricks hit at (approximately) the same time

  for (const brick of bricks) {
    if (!brick.alive) continue;
    const left = brick.x - r, right = brick.x + brick.w + r;
    const top = brick.y - r, bottom = brick.y + brick.h + r;

    let tEnter = 0, tExit = 1, face = null;
    let inside = prevX >= left && prevX <= right && prevY >= top && prevY <= bottom;
    // slab method
    let txNear = -Infinity, txFar = Infinity, tyNear = -Infinity, tyFar = Infinity;
    if (dx === 0) {
      if (prevX < left || prevX > right) continue;   // no horizontal travel, outside x-range
    } else if (dx > 0) {
      txNear = (left - prevX) / dx; txFar = (right - prevX) / dx;
    } else {
      txNear = (right - prevX) / dx; txFar = (left - prevX) / dx;
    }
    if (dy === 0) {
      if (prevY < top || prevY > bottom) continue;
    } else if (dy > 0) {
      tyNear = (top - prevY) / dy; tyFar = (bottom - prevY) / dy;
    } else {
      tyNear = (bottom - prevY) / dy; tyFar = (top - prevY) / dy;
    }
    tEnter = Math.max(txNear, tyNear);
    tExit = Math.min(txFar, tyFar);
    if (tEnter > tExit || tEnter > 1 || tExit < 0) continue;

    // face of the entry
    if (inside || tEnter <= 0) {
      face = null; // start inside: resolve by min-penetration at the end position
    } else if (tEnter === txNear && tEnter === tyNear) {
      face = 'corner';
    } else if (tEnter === txNear) {
      face = dx > 0 ? 'left' : 'right';
    } else {
      face = dy > 0 ? 'top' : 'bottom';
    }

    if (face === null) {
      // inside: min-penetration at end position
      ... compute overlapX/overlapY; pick axis; face = ...; tEnter = 0
    }

    if (tEnter < firstT - 1e-9) {
      firstT = tEnter; firstFace = face; firstBrick = brick; sameT.length = 0; sameT.push(brick);
    } else if (tEnter <= firstT + 1e-9) {
      sameT.push(brick);
    }
  }
  ...
}
```

