import { test } from 'node:test';
import assert from 'node:assert/strict';

import { step, createState, collides } from '../game/neon.js';

// brick helpers: col 0 row 0 at (4,48), col 1 row 0 at (84,48)
const brick = (s, row, col) => s.bricks[row * 8 + col];

test('D1: ball bounces off a brick top face (level 1, head-on)', () => {
  const s = createState(1);
  s.ball = { x: 40, y: 40, r: 7, vx: 0, vy: 260 }; // bottom edge 47, 1px above row 0
  const lost = step(s, 1 / 60);
  assert.equal(lost, false);
  assert.equal(s.ball.vy, -260, 'vy must flip (bounce)');
  assert.equal(s.ball.y, 41, 'ball pushed out to brick.y - r');
  assert.equal(brick(s, 0, 0).alive, false, 'brick destroyed');
  assert.equal(s.combo, 1);
  assert.equal(s.score, 75, 'row0 points 50 * combo 1.5');
  assert.equal(collides(s.ball, brick(s, 0, 0)), false, 'ball no longer overlaps');
});

test('D2: no tunneling — a step longer than the brick still bounces (level 7, dt=0.05)', () => {
  const s = createState(7); // ballSpeed 800
  s.ball = { x: 40, y: 40, r: 7, vx: 0, vy: 800 }; // dy = 40 > 34 (brick 20 + ball 14)
  const lost = step(s, 0.05);
  assert.equal(lost, false);
  assert.equal(s.ball.vy, -800, 'ball must bounce, not jump over the brick');
  assert.equal(s.ball.y, 41, 'ball pushed back out above the brick');
  assert.equal(brick(s, 0, 0).alive, false, 'crossed brick destroyed');
  assert.equal(brick(s, 1, 0).alive, true, 'brick behind the bounce point untouched');
  assert.ok(s.ball.y + s.ball.r < brick(s, 0, 0).y + brick(s, 0, 0).h, 'ball not below the brick');
});

test('D3: seam between two columns — one bounce, both bricks die', () => {
  const s = createState(1);
  s.ball = { x: 80, y: 40, r: 7, vx: 0, vy: 260 }; // straddles cols 0 and 1 (gap 8 < d 14)
  const lost = step(s, 1 / 60);
  assert.equal(lost, false);
  assert.equal(s.ball.vy, -260, 'vy flipped exactly once (no double inversion)');
  assert.equal(s.ball.y, 41);
  assert.equal(brick(s, 0, 0).alive, false, 'left seam brick destroyed');
  assert.equal(brick(s, 0, 1).alive, false, 'right seam brick destroyed');
  assert.equal(s.combo, 2);
  assert.equal(s.score, 175, '75 + 100');
  assert.equal(collides(s.ball, brick(s, 0, 0)), false);
  assert.equal(collides(s.ball, brick(s, 0, 1)), false);
});

test('D4a: side face hit flips vx only, vy unchanged', () => {
  const s = createState(1);
  brick(s, 0, 0).alive = false; // approach through the empty col 0 cell
  s.ball = { x: 70, y: 58, r: 7, vx: 260, vy: 50 }; // heading right into col 1 left face
  const lost = step(s, 0.05);
  assert.equal(lost, false);
  assert.equal(s.ball.vx, -260, 'vx flipped');
  assert.equal(s.ball.vy, 50, 'vy untouched on a side hit');
  assert.equal(s.ball.x, 77, 'pushed out to brick.x - r');
  assert.equal(brick(s, 0, 1).alive, false);
});

test('D4b: corner hit (equal penetration) flips both velocities', () => {
  const s = createState(1);
  brick(s, 0, 0).alive = false;
  s.ball = { x: 71, y: 35, r: 7, vx: 260, vy: 260 }; // 45° into col 1 top-left corner
  const lost = step(s, 0.05);
  assert.equal(lost, false);
  assert.equal(s.ball.vx, -260, 'vx flipped on corner');
  assert.equal(s.ball.vy, -260, 'vy flipped on corner');
  assert.equal(s.ball.x, 77);
  assert.equal(s.ball.y, 41);
  assert.equal(brick(s, 0, 1).alive, false);
});

test('D5: overlapping ball (previous miss) is pushed out, no re-flip, no stick', () => {
  const s = createState(1);
  s.ball = { x: 40, y: 44.33, r: 7, vx: 0, vy: 260 }; // already overlapping, moving into the brick
  const lost = step(s, 1 / 60);
  assert.equal(lost, false);
  assert.equal(s.ball.vy, -260, 'bounced once');
  assert.equal(s.ball.y, 41, 'pushed out of the brick');
  assert.equal(collides(s.ball, brick(s, 0, 0)), false, 'ball no longer overlaps the brick');
  assert.equal(brick(s, 0, 0).alive, false);
});

test('D6a: paddle — fast ball crossing the band still bounces (no high-speed tunneling)', () => {
  const s = createState(1);
  s.ball = { x: 320, y: 440.5, r: 7, vx: 0, vy: 260 }; // bottom edge 447.5, dy=13 > band 12
  const lost = step(s, 0.05);
  assert.equal(lost, false, 'ball must not be lost through the paddle');
  assert.equal(s.ball.vy, -260);
  assert.equal(s.ball.y, 441, 'ball placed on top of the paddle');
});

test('D6b: ball already below the paddle stays lost (no phantom bounce)', () => {
  const s = createState(1);
  s.ball = { x: 320, y: 500, r: 7, vx: 0, vy: 260 };
  const lost = step(s, 0.05);
  assert.equal(lost, true);
  assert.equal(s.ball.vy, 260, 'no false bounce below the paddle');
});

# to_fix.md — playtest du symptôme « la balle traverse les briques »

**Symptôme (mot pour mot)** : « La balle traverse les briques au lieu de rebondir. Corrige ça. »

La cause première est triviale — `frame()` détruit la brique sans jamais dévier la balle
(le commentaire `BUG (#1)` le dit). Mais derrière ce premier défaut, la résolution de
collision n'existe pas du tout : une fois qu'on l'écrit, quatre autres défauts sortent.
Chaque bloc ci-dessous est un défaut distinct, avec son cas rouge exécuté sur le code
d'aujourd'hui (`ℹ fail 7`).

**Verbatim des dix familles — verdicts** :

| Famille | Verdict | Raison (tirée du code) |
| --- | --- | --- |
| Traversée | **D1 + D2** | `game/neon.js` `frame()` : `collides()` détruit la brique, ne dévie jamais la balle. Puis, une fois le rebond écrit, pas balayé : pas de rebond quand `pas > brique + diamètre`. |
| Collant | **D5** | Aucun repositionnement n'existe ; un rebond sans push-out laisserait la balle recouvrir la brique au tour suivant (ré-inversion). |
| Double inversion | **D3** | Écart entre colonnes = 8 px < diamètre 14 px : la balle peut recouvrir deux briques dans la même passe (couture). Résoudre chaque brique indépendamment = deux `vy = -vy` qui s'annulent. |
| Face vs coin | **D4** | Aucune résolution d'axe n'existe. La règle de référence (axe de moindre pénétration, coin = les deux axes) doit être spécifiée avant d'implémenter. |
| Paddle | **D6** | Capture : déjà empêchée (`ball.y = paddle.y - ball.r`). Téléportation : propriété du modèle souris, non reproductible en logique pure (et `paddle.x` est clampé). **Traversée par le haut** : test de bande discret `ball.y + ball.r ∈ [paddle.y, paddle.y + h]` — un pas plus long que la bande saute par-dessus → balle perdue. |
| Angle mort | écartée | `step()` : `ball.vx = ballSpeed(level) * 0.6 * hit` avec `hit = 0` → `vx = 0` possible sur un contact au centre. Mais `vy` n'est jamais nul (lancement `vy = -speed`), la trajectoire reste jouable ; c'est un réglage du rebond paddle, pas une traversée. |
| Vitesse | écartée | Le rebond paddle réécrit `vx` sans renormaliser : norme ∈ `[s, 1.166·s]`, bornée — c'est la déflexion angulaire standard du genre, pas une accélération/atténuation incontrôlée. Les rebonds brique (périmètre de ce ticket) sont de purs changements de signe : norme conservée exactement. |
| Dépendance à dt | écartée | Le correctif est balayé sur le segment `(position précédente → position courante)` : continu, indépendant du découpage de `dt` (les cas D1 à `dt = 1/60` et D2 à `dt = 0.05` donnent le même rebond). |
| Score / combo | écartée | `comboMultiplier` non borné = dette documentée (#5), inchangée. Le combo/score par brique tuée est déplacé tel quel de `frame()` vers `step()` ; le reset combo au paddle est déjà correct. |
| Transitions | écartée | La vérification de niveau terminé (`bricks.every(!alive)`) tourne dans `loop()` après `step()` : en déplaçant les tuiles brique de `frame()` vers `step()`, le passage de niveau devient synchrone (une frame plus tôt) — amélioration, pas défaut. |

Références (étape 1) : défaillances = « *tunneling* » / « *ghost collision* » / « *seam* » ;
résolutions = *swept AABB* (premier temps d'impact) et *axe de moindre pénétration*.

---

## D1 — Les briques ne renvoient jamais la balle

- **Famille** : traversée (cause racine du symptôme)
- **Symptôme joueur** : la balle traverse la brique de part en part, même à l'aller le plus lent — elle la détruit au passage sans jamais rebondir.
- **Cause** : `game/neon.js:198` — dans `frame()`, le bloc `if (collides(state.ball, brick))` détruit la brique, incrémente combo/score, et **ne touche jamais à la vélocité de la balle** (le commentaire `BUG (#1)` le déclare). Le seul rebond de brique est… absent ; `step()` ne connaît que murs et paddle.
- **Invariant violé** : *aucun obstacle franchi sans rebond, quel que soit le pas* — ici violé même au pas le plus petit.
- **Déclencheur** : niveau 1, n'importe quel `dt` : brique rangée 0 colonne 0 (`x:4, y:48, w:72, h:20`), balle `(x:40, y:40, r:7, vx:0, vy:+260)` descendante — après un pas `dt = 1/60` (`dy ≈ 4.33`), elle recouvre la brique (`ball.y + r = 51.33 > 48`) et continue.
- **Attendu** : `vy` passe de `+260` à `-260`, la balle est reposée à `y = brick.y - r = 41` (hors de la brique), la brique est détruite, combo 1, score 75 (`50 × 1.5`).
- **Référence** : <https://gamedev.net/tutorials/_/technical/game-programming/swept-aabb-collision-detection-and-response-r3084/> — une collision doit produire une réponse (normale de surface + repositionnement), pas seulement un marquage.
- **Cas test** :
  ```js
  test('D1: ball bounces off a brick top face (level 1, head-on)', () => {
    const s = createState(1);
    s.ball = { x: 40, y: 40, r: 7, vx: 0, vy: 260 }; // bottom edge 47, 1px above row 0
    const lost = step(s, 1 / 60);
    assert.equal(lost, false);
    assert.equal(s.ball.vy, -260, 'vy must flip (bounce)');
    assert.equal(s.ball.y, 41, 'ball pushed out to brick.y - r');
    assert.equal(brick(s, 0, 0).alive, false, 'brick destroyed');
    assert.equal(s.combo, 1);
    assert.equal(s.score, 75, 'row0 points 50 * combo 1.5');
    assert.equal(collides(s.ball, brick(s, 0, 0)), false, 'ball no longer overlaps');
  });
  ```
- **Rouge aujourd'hui** :
  ```
  ✖ D1: ball bounces off a brick top face (level 1, head-on)
  AssertionError [ERR_ASSERTION]: vy must flip (bounce)
  260 !== -260
  ℹ tests 8 / ℹ pass 1 / ℹ fail 7
  ```
- **Discrimine** : le code d'aujourd'hui (aucune déviation). C'est le défaut racine ; les cas D2–D5 sont écrits pour refuser les *corrections naïves* de celui-ci.
- **Vert quand** : un pas de balle en recouvrement avec une brique vivante produit un rebond, une sortie de la brique, et la destruction de celle-ci — le tout depuis `step()`, logique pure.

---

## D2 — Traversée par balayage manquant : à niveau 5+, un pas saute par-dessus une brique

- **Famille** : traversée (*tunneling*)
- **Symptôme joueur** : dès que la balle est rapide, elle passe au travers d'une rangée entière sans rien casser ni rebondir — surtout en cas de frame lente (`dt` proche de 50 ms).
- **Cause** : `game/neon.js:193` (`collides`) — test discret sur la position d'arrivée uniquement : si le segment parcouru saute de « au-dessus » à « en dessous » de la brique, aucune des deux positions ne recouvre. Pas de balayage entre les deux positions.
- **Invariant violé** : *aucun obstacle franchi sans rebond, quel que soit le pas*.
- **Déclencheur** : niveau ≥ 5. `ballSpeed(5) = 620` ; norme max après un rebond paddle ≈ `1.166·s` → pas maximal `1.166·620·0.05 = 36.2 px > 34 px` = hauteur de brique (20) + diamètre de balle (14). Cas exécuté : niveau 7 (`ballSpeed = 800`), balle `(40, 40)`, `vy = +800`, `dt = 0.05` → `dy = 40 px`, la balle finit à `y = 80` (bord bas `87 > 68`), sous la brique, sans jamais la toucher.
- **Attendu** : le segment `(40,40)→(40,80)` croise la brique rangée 0 (bords balayés `[41, 75]`) au temps `t = (41−40)/40 = 0.025` → rebond face haute : `vy = −800`, balle reposée à `y = 41`, brique rangée 0 détruite ; la brique rangée 1 (croisée à `t = 0.725`, *après* le point d'impact) reste intacte.
- **Référence** : <https://gamedev.net/tutorials/_/technical/game-programming/swept-aabb-collision-detection-and-response-r3084/> — *swept AABB* : calculer le premier temps d'impact le long du vecteur de déplacement et résoudre à ce temps ; <https://noonat.github.io/intersect/> — « sweep tests take the path of movement into account, and stop objects from ever moving into other objects » (`hit.time`).
- **Cas test** :
  ```js
  test('D2: no tunneling — a step longer than the brick still bounces (level 7, dt=0.05)', () => {
    const s = createState(7); // ballSpeed 800
    s.ball = { x: 40, y: 40, r: 7, vx: 0, vy: 800 }; // dy = 40 > 34 (brick 20 + ball 14)
    const lost = step(s, 0.05);
    assert.equal(lost, false);
    assert.equal(s.ball.vy, -800, 'ball must bounce, not jump over the brick');
    assert.equal(s.ball.y, 41, 'ball pushed back out above the brick');
    assert.equal(brick(s, 0, 0).alive, false, 'crossed brick destroyed');
    assert.equal(brick(s, 1, 0).alive, true, 'brick behind the bounce point untouched');
    assert.ok(s.ball.y + s.ball.r < brick(s, 0, 0).y + brick(s, 0, 0).h, 'ball not below the brick');
  });
  ```
- **Rouge aujourd'hui** :
  ```
  ✖ D2: no tunneling — a step longer than the brick still bounces (level 7, dt=0.05)
  AssertionError [ERR_ASSERTION]: ball must bounce, not jump over the brick
  800 !== -800
  ℹ fail 7
  ```
- **Discrimine** : la correction naïve « rebondir si la position d'arrivée recouvre la brique » — ici l'arrivée est *sous* la brique, aucun recouvrement → la correction naïve laisse passer la balle (cas rouge) ; seule la détection balayée du segment le refuse. Elle refuse aussi « tuer toutes les briques croisées » : la rangée 1 est derrière le point d'impact, elle doit survivre.
- **Vert quand** : un pas plus long que `brique + balle` produit quand même un rebond, et seules les briques touchées au premier temps d'impact meurent.
- **Révélé par** : D1 (invisible tant que la balle ne rebondit nulle part).

---

## D3 — Couture entre deux colonnes : double inversion, la balle ressort par le bas

- **Famille** : double inversion (*seam / ghost collision*)
- **Symptôme joueur** : la balle qui descend pile sur la jointure entre deux briques adjacentes les casse mais continue tout droit, comme si elle les avait traversées.
- **Cause** : à venir dans la résolution — si chaque brique recouverte est résolue indépendamment, chacune voit une face haute et fait `vy = -vy` : deux inversions s'annulent. L'écart entre colonnes (`BRICK_GAP = 8 px`) est plus petit que le diamètre de la balle (`14 px`) : la balle peut recouvrir **deux** briques dans la même passe.
- **Invariant violé** : *un rebond par passe et par axe*.
- **Déclencheur** : balle `(x:80, y:40, r:7, vx:0, vy:+260)`, `dt = 1/60` : elle s'étend de `73` à `87`, donc sur la colonne 0 (`4..76`) **et** la colonne 1 (`84..156`) ; les deux faces hautes sont croisées au même temps `t = (41−40)/4.33 ≈ 0.231`.
- **Attendu** : `vy` inversé **une seule fois** (`−260`), balle reposée à `y = 41`, **les deux** briques détruites, combo 2, score `75 + 100 = 175`.
- **Référence** : <http://briansemrau.github.io/dealing-with-ghost-collisions/> — une surface partagée (ici : deux briques de même rangée, même plan haut) ne doit jamais être résolue pièce par pièce avec des normales indépendantes : c'est la définition même de la *ghost collision* (normale qui se retourne, double résolution). Traiter la couture comme une seule surface → une seule résolution.
- **Cas test** :
  ```js
  test('D3: seam between two columns — one bounce, both bricks die', () => {
    const s = createState(1);
    s.ball = { x: 80, y: 40, r: 7, vx: 0, vy: 260 }; // straddles cols 0 and 1 (gap 8 < d 14)
    const lost = step(s, 1 / 60);
    assert.equal(lost, false);
    assert.equal(s.ball.vy, -260, 'vy flipped exactly once (no double inversion)');
    assert.equal(s.ball.y, 41);
    assert.equal(brick(s, 0, 0).alive, false, 'left seam brick destroyed');
    assert.equal(brick(s, 0, 1).alive, false, 'right seam brick destroyed');
    assert.equal(s.combo, 2);
    assert.equal(s.score, 175, '75 + 100');
    assert.equal(collides(s.ball, brick(s, 0, 0)), false);
    assert.equal(collides(s.ball, brick(s, 0, 1)), false);
  });
  ```
- **Rouge aujourd'hui** :
  ```
  ✖ D3: seam between two columns — one bounce, both bricks die
  AssertionError [ERR_ASSERTION]: vy flipped exactly once (no double inversion)
  260 !== -260
  ℹ fail 7
  ```
- **Discrimine** : la correction naïve « pour chaque brique recouverte : `vy = -vy` + push-out » — la première inversion est annulée par la seconde (`vy` redevient `+260`, le cas reste rouge) ; seul le « un rebond par axe et par passe » le refuse. Elle refuse aussi « ne détruire que la première brique » (le cas exige les deux).
- **Vert quand** : une passe recouvrant deux briques de même rangée produit exactement un rebond et détruit les deux.
- **Révélé par** : D1 (invisible tant que la balle ne rebondit nulle part).

---

## D4 — Face vs coin : l'axe du rebond dépend de la pénétration, coin = les deux axes

- **Famille** : face vs coin
- **Symptôme joueur** : une fois le rebond en place, la balle tape le *côté* d'une brique et rebondit à la verticale (mauvais axe), ou tape un coin et part dans une direction arbitraire.
- **Cause** : à venir dans la résolution — si on inverse systématiquement `vy` sur toute collision (correction naïve), les faces latérales sont mal résolues ; si on choisit l'axe par un tirage arbitraire, le coin (pénétrations égales) est perdu.
- **Invariant violé** : *l'axe touché est celui de la plus petite pénétration ; à pénétration égale (coin), les deux vitesses sont inversées*.
- **Déclencheur** (brique colonne 1 rangée 0, `x:84, y:48`) :
  - Face latérale : balle `(70, 58)`, `vx:+260, vy:+50`, `dt = 0.05` → entrée par la face gauche (balayé, `t = 7/13 ≈ 0.538`) ; à l'arrivée `(83, 60.5)`, pénétration `x = 6 < y = 19.5`.
  - Coin : balle `(71, 35)`, `vx:+260, vy:+260`, `dt = 0.05` → arrivée exacte au coin `(84, 48)` : pénétrations `x = 7` et `y = 7`, **égales**.
- **Attendu** : face latérale → `vx` devient `−260`, `vy` reste `50`, balle reposée à `x = 77` ; coin → `vx` **et** `vy` deviennent `−260`, balle reposée à `(77, 41)`.
- **Référence** : <https://noonat.github.io/intersect/> — « we find the axis with the smallest overlap and use that to create an intersection point on the edge of the box » (`hit.delta` = vecteur de sortie) ; cas dégénéré : pénétration égale sur les deux axes → contact au coin.
- **Cas test** :
  ```js
  test('D4a: side face hit flips vx only, vy unchanged', () => {
    const s = createState(1);
    brick(s, 0, 0).alive = false; // approach through the empty col 0 cell
    s.ball = { x: 70, y: 58, r: 7, vx: 260, vy: 50 }; // heading right into col 1 left face
    const lost = step(s, 0.05);
    assert.equal(lost, false);
    assert.equal(s.ball.vx, -260, 'vx flipped');
    assert.equal(s.ball.vy, 50, 'vy untouched on a side hit');
    assert.equal(s.ball.x, 77, 'pushed out to brick.x - r');
    assert.equal(brick(s, 0, 1).alive, false);
  });

  test('D4b: corner hit (equal penetration) flips both velocities', () => {
    const s = createState(1);
    brick(s, 0, 0).alive = false;
    s.ball = { x: 71, y: 35, r: 7, vx: 260, vy: 260 }; // 45° into col 1 top-left corner
    const lost = step(s, 0.05);
    assert.equal(lost, false);
    assert.equal(s.ball.vx, -260, 'vx flipped on corner');
    assert.equal(s.ball.vy, -260, 'vy flipped on corner');
    assert.equal(s.ball.x, 77);
    assert.equal(s.ball.y, 41);
    assert.equal(brick(s, 0, 1).alive, false);
  });
  ```
- **Rouge aujourd'hui** :
  ```
  ✖ D4a: side face hit flips vx only, vy unchanged
  AssertionError [ERR_ASSERTION]: vx flipped
  260 !== -260
  ✖ D4b: corner hit (equal penetration) flips both velocities
  AssertionError [ERR_ASSERTION]: vx flipped on corner
  260 !== -260
  ℹ fail 7
  ```
- **Discrimine** : D4a refuse « inverser `vy` sur toute collision » (vy passe à `−50`, cas rouge) ; D4b refuse « inverser un seul axe » et « moindre pénétration avec égalité départagée arbitrairement » (le coin exige les deux axes).
- **Vert quand** : face latérale → seul `vx` change ; coin (pénétrations égales) → `vx` et `vy` changent.
- **Révélé par** : D1 (invisible tant que la balle ne rebondit nulle part).

---

## D5 — Collant : un rebond sans repositionnement laisse la balle vibrer dans la brique

- **Famille** : collant
- **Symptôme joueur** : la balle semble « coller » à une brique, vibrer sur place ou repartir dans la brique au lieu de s'en éloigner.
- **Cause** : à venir dans la résolution — une inversion de vitesse **sans push-out** laisse la balle en recouvrement au tour suivant : le test re-détecte, ré-inverse, la balle vibre ou repart dans l'obstacle.
- **Invariant violé** : *après résolution, la balle est hors du rectangle*.
- **Déclencheur** : balle déjà en recouvrement (erreur de la frame précédente) `(x:40, y:44.33, r:7)`, `vy:+260` (elle rentre dans la brique), `dt = 1/60` → centre initial dans la brique gonflée → résolution par moindre pénétration : `y = 7.66 < x = 43` → axe vertical, sortie par le haut.
- **Attendu** : `vy` devient `−260` (une seule inversion), balle reposée à `y = 41`, plus aucun recouvrement avec la brique.
- **Référence** : <https://noonat.github.io/intersect/> — un test d'intersection statique renvoie `hit.delta` : le vecteur qui, ajouté à la position, la ramène hors du rectangle. Sans lui, l'état de contact « flickers between touching and not touching » (Semrau, cf. D3).
- **Cas test** :
  ```js
  test('D5: overlapping ball (previous miss) is pushed out, no re-flip, no stick', () => {
    const s = createState(1);
    s.ball = { x: 40, y: 44.33, r: 7, vx: 0, vy: 260 }; // already overlapping, moving into the brick
    const lost = step(s, 1 / 60);
    assert.equal(lost, false);
    assert.equal(s.ball.vy, -260, 'bounced once');
    assert.equal(s.ball.y, 41, 'pushed out of the brick');
    assert.equal(collides(s.ball, brick(s, 0, 0)), false, 'ball no longer overlaps the brick');
    assert.equal(brick(s, 0, 0).alive, false);
