```js
// --- Brick collisions (swept, pure) ----------------------------------------

// Resolves the ball against every live brick, using the path it travelled
// during this step (from (prevX, prevY) to its current position).
//
// Each brick is inflated by the ball radius so the ball acts as a point, and
// the slab method gives the first time of impact along the segment. The
// EARLIEST impact is the only one resolved (one bounce per pass): bricks
// entered at the same time — the seam between two columns of a row — all die,
// but the velocity of each axis is flipped at most once, so a seam hit cannot
// invert vy twice and tunnel. Bricks entered later along the segment are
// behind the impact point and stay untouched.
export function resolveBricks(state, prevX, prevY) {
  const { ball, bricks } = state;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;
  const r = ball.r;

  let first = null;      // earliest impact
  let firstT = Infinity;
  const sameTime = [];   // bricks entered at (≈) the same time as `first`

  for (const brick of bricks) {
    if (!brick.alive) continue;

    const left = brick.x - r;
    const right = brick.x + brick.w + r;
    const top = brick.y - r;
    const bottom = brick.y + brick.h + r;

    let t;
    let face;
    if (collides({ x: prevX, y: prevY, r }, brick)) {
      // Already overlapping at the start of the step (a previous frame left
      // it inside): resolve statically, on the axis of smallest penetration.
      const penL = ball.x + r - brick.x;
      const penR = brick.x + brick.w - (ball.x - r);
      const penT = ball.y + r - brick.y;
      const penB = brick.y + brick.h - (ball.y - r);
      const penX = Math.min(penL, penR);
      const penY = Math.min(penT, penB);
      if (Math.abs(penX - penY) < EPS) face = 'corner';
      else if (penX < penY) face = penL < penR ? 'left' : 'right';
      else face = penT < penB ? 'top' : 'bottom';
      t = 0;
    } else {
      // Swept: slab method, first time the segment enters the inflated box.
      let txNear = -Infinity;
      let txFar = Infinity;
      if (dx === 0) {
        if (prevX < left || prevX > right) continue;
      } else if (dx > 0) {
        txNear = (left - prevX) / dx;
        txFar = (right - prevX) / dx;
      } else {
        txNear = (right - prevX) / dx;
        txFar = (left - prevX) / dx;
      }
      let tyNear = -Infinity;
      let tyFar = Infinity;
      if (dy === 0) {
        if (prevY < top || prevY > bottom) continue;
      } else if (dy > 0) {
        tyNear = (top - prevY) / dy;
        tyFar = (bottom - prevY) / dy;
      } else {
        tyNear = (bottom - prevY) / dy;
        tyFar = (top - prevY) / dy;
      }
      const tEnter = Math.max(txNear, tyNear);
      const tExit = Math.min(txFar, tyFar);
      if (tEnter > tExit || tEnter > 1 || tExit < 0) continue;

      // Face: the edge the segment enters through; a corner entry (both near
      // times equal) flips both axes.
      const entryX = prevX + tEnter * dx;
      const entryY = prevY + tEnter * dy;
      const onCorner =
        (Math.abs(entryX - left) < EPS && (Math.abs(entryY - top) < EPS || Math.abs(entryY - bottom) < EPS)) ||
        (Math.abs(entryX - right) < EPS && (Math.abs(entryY - top) < EPS || Math.abs(entryY - bottom) < EPS));
      if (onCorner) face = 'corner';
      else if (tEnter === txNear) face = dx > 0 ? 'left' : 'right';
      else face = dy > 0 ? 'top' : 'bottom';
      t = tEnter;
    }

    if (t < firstT - EPS) {
      firstT = t;
      first = { brick, face };
      sameTime.length = 0;
      sameTime.push(brick);
    } else if (t <= firstT + EPS) {
      sameTime.push(brick);
    }
  }

  if (!first) return;

  // Every brick hit at the time of impact breaks (seam included)…
  for (const brick of sameTime) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  // …and the ball bounces off the FIRST face, once per axis.
  const { brick, face } = first;
  switch (face) {
    case 'top':
      ball.y = brick.y - r;
      if (ball.vy > 0) ball.vy = -ball.vy;
      break;
    case 'bottom':
      ball.y = brick.y + brick.h + r;
      if (ball.vy < 0) ball.vy = -ball.vy;
      break;
    case 'left':
      ball.x = brick.x - r;
      if (ball.vx > 0) ball.vx = -ball.vx;
      break;
    case 'right':
      ball.x = brick.x + brick.w + r;
      if (ball.vx < 0) ball.vx = -ball.vx;
      break;
    case 'corner':
      ball.x = ball.x < brick.x + brick.w / 2 ? brick.x - r : brick.x + brick.w + r;
      ball.y = ball.y < brick.y + brick.h / 2 ? brick.y - r : brick.y + brick.h + r;
      ball.vx = -ball.vx;
      ball.vy = -ball.vy;
      break;
  }
}
```

