// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

// --- Brick collision tests (see .scratch/to_fix.md, D1–D5) -----------------

// The grid is row-major: brick at (row, col) of the level.
const brick = (s, row, col) => s.bricks[row * BRICK_COLS + col];

// D1 — the primary defect: bricks never bounce the ball (frame() destroyed
// them without deflecting it). A slow head-on descent must bounce, push the
// ball out, and break the brick — all from step(), pure logic.
test('D1: ball bounces off a brick top face (level 1, head-on)', () => {
  const s = createState(1);
  s.ball = { x: 40, y: 40, r: 7, vx: 0, vy: 260 }; // bottom edge 47, 1px above row 0
  const lost = step(s, 1 / 60);
  assert.equal(lost, false);
  assert.equal(s.ball.vy, -260, 'vy must flip (bounce)');
  assert.equal(s.ball.y, 41, 'ball pushed out to brick.y - r');
  assert.equal(brick(s, 0, 0).alive, false, 'brick destroyed');
  assert.equal(s.combo, 1);
  assert.equal(s.score, 75, 'row0 points 50 * combo 1.5');
  assert.equal(collides(s.ball, brick(s, 0, 0)), false, 'ball no longer overlaps');
});

// D2 — tunneling: at high speed a single step is longer than (brick + ball)
// and jumps over the brick without ever overlapping it. The resolution must
// sweep the travelled segment, not test the arrival position only.
test('D2: no tunneling — a step longer than the brick still bounces (level 7, dt=0.05)', () => {
  const s = createState(7); // ballSpeed 800
  s.ball = { x: 40, y: 40, r: 7, vx: 0, vy: 800 }; // dy = 40 > 34 (brick 20 + ball 14)
  const lost = step(s, 0.05);
  assert.equal(lost, false);
  assert.equal(s.ball.vy, -800, 'ball must bounce, not jump over the brick');
  assert.equal(s.ball.y, 41, 'ball pushed back out above the brick');
  assert.equal(brick(s, 0, 0).alive, false, 'crossed brick destroyed');
  assert.equal(brick(s, 1, 0).alive, true, 'brick behind the bounce point untouched');
  assert.ok(s.ball.y + s.ball.r < brick(s, 0, 0).y + brick(s, 0, 0).h, 'ball not below the brick');
});

// D3 — seam / ghost collision: the 8px gap between columns is smaller than
// the 14px ball, so a descent on the seam overlaps two bricks in one pass.
// Resolving each independently would flip vy twice and tunnel; one bounce per
// pass per axis, both bricks break.
test('D3: seam between two columns — one bounce, both bricks die', () => {
  const s = createState(1);
  s.ball = { x: 80, y: 40, r: 7, vx: 0, vy: 260 }; // straddles cols 0 and 1 (gap 8 < d 14)
  const lost = step(s, 1 / 60);
  assert.equal(lost, false);
  assert.equal(s.ball.vy, -260, 'vy flipped exactly once (no double inversion)');
  assert.equal(s.ball.y, 41);
  assert.equal(brick(s, 0, 0).alive, false, 'left seam brick destroyed');
  assert.equal(brick(s, 0, 1).alive, false, 'right seam brick destroyed');
  assert.equal(s.combo, 2);
  assert.equal(s.score, 175, '75 + 100');
  assert.equal(collides(s.ball, brick(s, 0, 0)), false);
  assert.equal(collides(s.ball, brick(s, 0, 1)), false);
});

// D4 — face vs corner: the bounce axis is the smallest penetration; a side
// hit flips vx only, an exact corner hit (equal penetration) flips both.
test('D4a: side face hit flips vx only, vy unchanged', () => {
  const s = createState(1);
  brick(s, 0, 0).alive = false; // approach through the empty col 0 cell
  s.ball = { x: 70, y: 58, r: 7, vx: 260, vy: 50 }; // heading right into col 1 left face
  const lost = step(s, 0.05);
  assert.equal(lost, false);
  assert.equal(s.ball.vx, -260, 'vx flipped');
  assert.equal(s.ball.vy, 50, 'vy untouched on a side hit');
  assert.equal(s.ball.x, 77, 'pushed out to brick.x - r');
  assert.equal(brick(s, 0, 1).alive, false);
});

test('D4b: corner hit (equal penetration) flips both velocities', () => {
  const s = createState(1);
  brick(s, 0, 0).alive = false;
  s.ball = { x: 71, y: 35, r: 7, vx: 260, vy: 260 }; // 45° into col 1 top-left corner
  const lost = step(s, 0.05);
  assert.equal(lost, false);
  assert.equal(s.ball.vx, -260, 'vx flipped on corner');
  assert.equal(s.ball.vy, -260, 'vy flipped on corner');
  assert.equal(s.ball.x, 77);
  assert.equal(s.ball.y, 41);
  assert.equal(brick(s, 0, 1).alive, false);
});

// D5 — sticky: a ball already overlapping the brick (left by a previous
// miss) must be pushed back out and flipped exactly once, not re-flipped
// frame after frame.
test('D5: overlapping ball (previous miss) is pushed out, no re-flip, no stick', () => {
  const s = createState(1);
  s.ball = { x: 40, y: 44.33, r: 7, vx: 0, vy: 260 }; // already overlapping, moving into the brick
  const lost = step(s, 1 / 60);
  assert.equal(lost, false);
  assert.equal(s.ball.vy, -260, 'bounced once');
  assert.equal(s.ball.y, 41, 'pushed out of the brick');
  assert.equal(collides(s.ball, brick(s, 0, 0)), false, 'ball no longer overlaps the brick');
  assert.equal(brick(s, 0, 0).alive, false);
});

