// --- Physics (movement + wall/paddle/brick bounces) -----------------------

// Resolves the ball against every live brick, sweeping the path it travelled
// during this step: from (prevX, prevY) to its current position. Each brick
// is inflated by the ball radius (the ball acts as a point) and the slab
// method gives the FIRST time of impact along the segment — so a fast step
// that jumps over a brick still bounces instead of tunnelling.
//
// The earliest impact is the only one resolved (one bounce per pass per
// axis). Bricks entered at the same time of impact — a seam between two
// columns of the same row, where the 8px gap is smaller than the 14px ball —
// all break, but the velocity of each axis flips at most once, so a seam hit
// cannot invert vy twice and tunnel. Bricks entered later along the segment
// sit behind the impact point and stay untouched.
//
// The bounce face is the edge the segment enters through: a top/bottom hit
// flips vy, a side hit flips vx, and an exact corner hit (equal penetration
// on both axes) flips both. The ball is pushed back out of the brick along
// the resolved face, so it never starts the next step overlapping (no stick).
function resolveBricks(state, prevX, prevY) {
  const { ball, bricks } = state;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;
  const r = ball.r;

  let first = null; // earliest impact
  let firstT = Infinity;
  const sameTime = []; // bricks entered at (≈) the same time as `first`

  for (const brick of bricks) {
    if (!brick.alive) continue;

    const left = brick.x - r;
    const right = brick.x + brick.w + r;
    const top = brick.y - r;
    const bottom = brick.y + brick.h + r;

    let t;
    let face;
    if (collides({ x: prevX, y: prevY, r }, brick)) {
      // Already overlapping at the start of the step (left inside by a
      // previous miss): resolve statically, on the axis of smallest
      // penetration.
      const penL = ball.x + r - brick.x;
      const penR = brick.x + brick.w - (ball.x - r);
      const penT = ball.y + r - brick.y;
      const penB = brick.y + brick.h - (ball.y - r);
      const penX = Math.min(penL, penR);
      const penY = Math.min(penT, penB);
      if (Math.abs(penX - penY) < EPS) face = 'corner';
      else if (penX < penY) face = penL < penR ? 'left' : 'right';
      else face = penT < penB ? 'top' : 'bottom';
      t = 0;
    } else {
      // Swept: slab method — first time the segment enters the inflated box.
      let txNear = -Infinity;
      let txFar = Infinity;
      if (dx === 0) {
        if (prevX < left || prevX > right) continue;
      } else if (dx > 0) {
        txNear = (left - prevX) / dx;
        txFar = (right - prevX) / dx;
      } else {
        txNear = (right - prevX) / dx;
        txFar = (left - prevX) / dx;
      }
      let tyNear = -Infinity;
      let tyFar = Infinity;
      if (dy === 0) {
        if (prevY < top || prevY > bottom) continue;
      } else if (dy > 0) {
        tyNear = (top - prevY) / dy;
        tyFar = (bottom - prevY) / dy;
      } else {
        tyNear = (bottom - prevY) / dy;
        tyFar = (top - prevY) / dy;
      }
      const tEnter = Math.max(txNear, tyNear);
      const tExit = Math.min(txFar, tyFar);
      if (tEnter > tExit || tEnter > 1 || tExit < 0) continue;

      // Face: the edge the segment enters through; a corner entry (the entry
      // point sits on an inflated corner) flips both axes.
      const entryX = prevX + tEnter * dx;
      const entryY = prevY + tEnter * dy;
      const onCorner =
        (Math.abs(entryX - left) < EPS && (Math.abs(entryY - top) < EPS || Math.abs(entryY - bottom) < EPS)) ||
