      else if (tEnter === txNear) face = dx > 0 ? 'left' : 'right';
      else face = dy > 0 ? 'top' : 'bottom';
      t = tEnter;
    }

    if (t < firstT - EPS) {
      firstT = t;
      first = { brick, face };
      sameTime.length = 0;
      sameTime.push(brick);
    } else if (t <= firstT + EPS) {
      sameTime.push(brick);
    }
  }

  if (!first) return;

  // Every brick hit at the time of impact breaks (seam included)…
  for (const brick of sameTime) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  // …and the ball bounces off the FIRST face, once per axis. A velocity
  // component is only flipped when it points INTO the brick (an overlapping
  // ball already leaving is pushed out, not trapped).
  const { brick, face } = first;
  switch (face) {
    case 'top':
      ball.y = brick.y - r;
      if (ball.vy > 0) ball.vy = -ball.vy;
      break;
    case 'bottom':
      ball.y = brick.y + brick.h + r;
      if (ball.vy < 0) ball.vy = -ball.vy;
      break;
    case 'left':
      ball.x = brick.x - r;
      if (ball.vx > 0) ball.vx = -ball.vx;
      break;
    case 'right':
      ball.x = brick.x + brick.w + r;
      if (ball.vx < 0) ball.vx = -ball.vx;
      break;
    case 'corner':
      ball.x = ball.x < brick.x + brick.w / 2 ? brick.x - r : brick.x + brick.w + r;
      ball.y = ball.y < brick.y + brick.h / 2 ? brick.y - r : brick.y + brick.h + r;
      ball.vx = -ball.vx;
      ball.vy = -ball.vy;
      break;
  }
}

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the bricks and the paddle. Brick collisions are swept against
// the segment travelled during the step (see resolveBricks), and the paddle
// is tested by crossing the slab, not by landing inside its 12px band — a
// fast ball must not jump over it.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const prevX = ball.x;
  const prevY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

