// Bricks: swept resolution, one bounce per pass per axis.
resolveBricks(state, prevX, prevY);

// Paddle: bounce if the ball's bottom edge CROSSES the paddle slab during
// this step (it used to have to land inside the 12px band, so a fast ball
// jumped over the paddle and was lost).
if (ball.vy > 0) {
  const prevBottom = prevY + ball.r;
  const newBottom = ball.y + ball.r;
  if (
    prevBottom <= paddle.y + paddle.h &&
    newBottom >= paddle.y &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
