arguments.command:
node -e "
import('./game/neon.js').then(({ createState, step, WIDTH, HEIGHT }) => {
  for (const level of [1, 4, 7]) {
    const s = createState(level);
    let lost = 0, minY = Infinity, maxY = 0, minX = Infinity, maxX = 0;
    for (let i = 0; i < 20000; i++) {
      const dt = 1 / 60;
      const res = step(s, dt);
      minY = Math.min(minY, s.ball.y); maxY = Math.max(maxY, s.ball.y);
      minX = Math.min(minX, s.ball.x); maxX = Math.max(maxX, s.ball.x);
      if (!Number.isFinite(s.ball.x) || !Number.isFinite(s.ball.y) || !Number.isFinite(s.ball.vx) || !Number.isFinite(s.ball.vy)) throw new Error('NaN at L'+level+' step '+i);
      if (res) { lost++; s.ball = createState(level).ball; }
      // level up if cleared
      if (s.bricks.every(b => !b.alive)) { s.bricks = (await import('./game/neon.js')).makeBricks(s.level); }
    }
    const alive = s.bricks.filter(b => b.alive).length;
    console.log('L'+level, 'lost', lost, 'bricks alive', alive, 'x range', minX.toFixed(1)+'..'+maxX.toFixed(1), 'y range', minY.toFixed(1)+'..'+maxY.toFixed(1), 'score', s.score, 'combo', s.combo);
  }
});
"

