    minX = Math.min(minX, s.ball.x); maxX = Math.max(maxX, s.ball.x);
    if (![s.ball.x, s.ball.y, s.ball.vx, s.ball.vy].every(Number.isFinite)) throw new Error('NaN at L'+level+' step '+i);
    if (res) { lost++; s.ball = createState(level).ball; }
    if (s.bricks.every(b => !b.alive)) { s.bricks = makeBricks(s.level); }
  }
  const alive = s.bricks.filter(b => b.alive).length;
  console.log('L'+level, '| lost:', lost, '| bricks alive:', alive, '| x:', minX.toFixed(1)+'..'+maxX.toFixed(1), '| y:', minY.toFixed(1)+'..'+maxY.toFixed(1), '| score:', s.score, '| combo:', s.combo);
}
"

node --input-type=module -e "
import { createState, step, makeBricks, WIDTH, PADDLE_W } from './game/neon.js';
let s = createState(1);
let broken = 0, lost = 0, levels = 0;
for (let i = 0; i < 60000; i++) {
  // paddle follows the ball
  s.paddle.x = Math.max(0, Math.min(WIDTH - PADDLE_W, s.ball.x - PADDLE_W / 2));
  if (step(s, 1 / 60)) { lost++; s.ball = createState(s.level).ball; }
  const dead = s.bricks.filter(b => !b.alive).length;
  if (dead !== broken) { broken = dead; }
  if (s.bricks.every(b => !b.alive)) { levels++; s.level += 1; s.bricks = makeBricks(s.level); s.ball = createState(s.level).ball; }
}
console.log('level', s.level, '| bricks broken total:', broken, '| levels cleared:', levels, '| lost:', lost, '| score:', s.score, '| combo:', s.combo);
console.log('bricks alive:', s.bricks.filter(b=>b.alive).length, '/', s.bricks.length);
"

