  const prev = s.bricks.filter(b=>!b.alive).length;
  step(s, 1 / 60);
  const dead = s.bricks.filter(b=>!b.alive).length;
  if (dead > prev && first > 0) {
    console.log('step', i, 'killed', dead - prev, '| ball (', s.ball.x.toFixed(1)+','+s.ball.y.toFixed(1)+') vx', s.ball.vx.toFixed(1), 'vy', s.ball.vy.toFixed(1), 'combo', s.combo);
