node --input-type=module -e "
import { createState, frame, step } from './game/neon.js';
const calls = [];
const ctx = new Proxy({}, { get: (t, p) => (...a) => { calls.push([p, ...a]); }, set: () => true });
const s = createState(1);
frame(ctx, s);            // fresh render
s.ball = { x: 40, y: 40, r: 7, vx: 0, vy: 260 };
step(s, 1 / 60);          // break a brick
frame(ctx, s);            // render after a kill
console.log('frame() OK —', calls.length, 'draw calls; brick dead:', s.bricks[0].alive === false);
" && rm -rf .scratch && npm test 2>&1 | tail -8
